package com.omnistyle

import com.facebook.react.module.annotations.ReactModule
import com.facebook.react.uimanager.SimpleViewManager
import com.facebook.react.uimanager.ThemedReactContext
import com.facebook.react.uimanager.ViewManagerDelegate
import com.facebook.react.uimanager.annotations.ReactProp
import com.facebook.react.viewmanagers.OmniAudioViewManagerDelegate
import com.facebook.react.viewmanagers.OmniAudioViewManagerInterface

/**
 * Bridge between Fabric and `OmniAudioView`: props, commands and events.
 * `OmniAudioViewManagerInterface`/`Delegate` are generated by Codegen from
 * `src/adapters/react-native/media/audio/native/OmniAudioViewNativeComponent.ts`.
 */
@ReactModule(name = OmniAudioViewManager.NAME)
class OmniAudioViewManager :
  SimpleViewManager<OmniAudioView>(),
  OmniAudioViewManagerInterface<OmniAudioView> {

  private val delegate = OmniAudioViewManagerDelegate(this)

  override fun getDelegate(): ViewManagerDelegate<OmniAudioView> = delegate

  override fun getName(): String = NAME

  override fun createViewInstance(context: ThemedReactContext): OmniAudioView = OmniAudioView(context)

  override fun onDropViewInstance(view: OmniAudioView) {
    view.release()
    super.onDropViewInstance(view)
  }

  // ── props ──

  @ReactProp(name = "src")
  override fun setSrc(view: OmniAudioView, value: String?) = view.setSource(value)

  @ReactProp(name = "controls", defaultBoolean = true)
  override fun setControls(view: OmniAudioView, value: Boolean) = view.setControls(value)

  @ReactProp(name = "autoPlay")
  override fun setAutoPlay(view: OmniAudioView, value: Boolean) = view.setAutoPlay(value)

  @ReactProp(name = "loop")
  override fun setLoop(view: OmniAudioView, value: Boolean) = view.setLoop(value)

  @ReactProp(name = "muted")
  override fun setMuted(view: OmniAudioView, value: Boolean) = view.setMuted(value)

  @ReactProp(name = "rate", defaultFloat = 1f)
  override fun setRate(view: OmniAudioView, value: Float) = view.setRate(value)

  @ReactProp(name = "volume", defaultFloat = 1f)
  override fun setVolume(view: OmniAudioView, value: Float) = view.setVolume(value)

  @ReactProp(name = "title")
  override fun setTitle(view: OmniAudioView, value: String?) = view.setTitle(value)

  @ReactProp(name = "artist")
  override fun setArtist(view: OmniAudioView, value: String?) = view.setArtist(value)

  @ReactProp(name = "playlistIndex", defaultInt = -1)
  override fun setPlaylistIndex(view: OmniAudioView, value: Int) = view.setPlaylist(value, view.playlistCount)

  @ReactProp(name = "playlistCount")
  override fun setPlaylistCount(view: OmniAudioView, value: Int) = view.setPlaylist(view.playlistIndex, value)

  @ReactProp(name = "artwork")
  override fun setArtwork(view: OmniAudioView, value: String?) = view.setArtwork(value)

  // ── commands ──

  override fun play(view: OmniAudioView) = view.play()

  override fun pause(view: OmniAudioView) = view.pause()

  override fun seekTo(view: OmniAudioView, seconds: Double) = view.seekTo(seconds)

  // ── events (native name → JS prop) ──

  override fun getExportedCustomDirectEventTypeConstants(): Map<String, Any> =
    OmniAudioView.EVENTS.associateWith { mapOf("registrationName" to "on" + it.removePrefix("top")) }

  companion object {
    const val NAME = "OmniAudioView"
  }
}
